36	import { toRequest } from "./utils/request.ts";
37	import { toEventHandler } from "./handler.ts";
38	
39	export const NoHandler: EventHandler = () => kNotFound;
40	
41	export class H3Core implements H3CoreType {
42	  static "~h3" = true;
43	
44	  readonly config: H3CoreConfig;
45	
46	  "~middleware": Middleware[];
47	  "~routes": H3Route[] = [];
48	
49	  // Cached dispatch and `~middleware` composition (invalidated by `use()` and `mount()`)
50	  "~dispatch"?: (event: H3Event, route: MatchedRoute<H3Route> | void) => unknown | Promise<unknown>;
51	  "~composed"?: ComposedMiddleware;
52	
53	  constructor(config: H3CoreConfig = {}) {
54	    this["~middleware"] = [];
55	    this.config = config;
56	    this.fetch = this.fetch.bind(this);
57	    this.handler = this.handler.bind(this);
58	  }
59	
60	  fetch(request: ServerRequest): Response | Promise<Response> {
61	    return this["~request"](request);
62	  }
63	
64	  handler(event: H3Event): unknown | Promise<unknown> {
65	    const route = this["~findRoute"](event);
66	    if (route) {
67	      event.context.params = route.params;
68	      event.context.matchedRoute = route.data;
69	    }
70	    return (this["~dispatch"] ??= createDispatcher(this))(event, route);
71	  }
72	
73	  "~request"(request: ServerRequest, context?: H3EventContext): Response | Promise<Response> {
74	    // Create a new event instance
75	    const event = new H3Event(request, context, this as unknown as H3Type);
76	
77	    // Execute the handler
78	    let handlerRes: unknown | Promise<unknown>;
79	    try {
80	      if ((event as any)[kMalformedURL] && !this.config.allowMalformedURL) {
81	        // Reject malformed request URLs before any routing or app logic runs.
82	        // Opt out with `allowMalformedURL` to receive the raw pathname instead.
83	        throw new HTTPError({ status: 400, message: "Bad Request" });
84	      }
85	      if (this.config.onRequest) {
86	        const hookRes = this.config.onRequest(event);
87	        handlerRes =
88	          typeof hookRes?.then === "function"
89	            ? hookRes.then(() => this.handler(event))
90	            : this.handler(event);
91	      } else {
92	        handlerRes = this.handler(event);
93	      }
94	    } catch (error: any) {
95	      handlerRes = Promise.reject(error);
96	    }
97	
98	    // Prepare response
99	    return toResponse(handlerRes, event, this.config);
100	  }
101	
102	  "~findRoute"(_event: H3Event): MatchedRoute<H3Route> | void {}
103	
104	  "~addRoute"(_route: H3Route): void {
105	    this["~routes"].push(_route);
106	  }
107	
108	  // Overriding `~getMiddleware` opts out of the precomposed fast path (see `createDispatcher`)
109	  "~getMiddleware"(_event: H3Event, _route?: MatchedRoute<H3Route>): Middleware[] {
110	    return this["~middleware"];
111	  }
112	}
