114	/**
115	 * Builds the cached per-app dispatch function. The custom `~getMiddleware` check runs
116	 * only here — once per composition (first request, or after `use()`/`mount()`
117	 * invalidation) — never per request.
118	 */
119	function createDispatcher(app: H3Core): NonNullable<H3Core["~dispatch"]> {
120	  if (app["~getMiddleware"] !== H3Core.prototype["~getMiddleware"]) {
121	    // Compat: a custom `~getMiddleware` (subclass or instance override)
122	    // can return per-event middleware, which cannot be precomposed.
123	    return (event, route) =>
124	      callMiddleware(event, app["~getMiddleware"](event, route || undefined), routeHandler(route));
125	  }
126	  const middleware = app["~middleware"];
127	  if (middleware.length === 0) {
128	    return (event, route) => routeHandler(route)(event);
129	  }
130	  const composed = (app["~composed"] ??= composeMiddleware(middleware));
131	  return (event, route) => composed(event, routeHandler(route));
132	}
