134	function routeHandler(route: MatchedRoute<H3Route> | void): EventHandler {
135	  const data = route?.data;
136	  if (!data) {
137	    return NoHandler;
138	  }
139	  // Route middleware and handler are fixed at registration: compose them once.
140	  // The composed pair travels with the route object when copied (mount).
141	  return data.middleware?.length
142	    ? (data["~composed"] ??= composeHandler(data.middleware, data.handler))
143	    : data.handler;
144	}
