    (H3Core as any).prototype[method.toLowerCase()] = function (
      this: H3Type,
      route: string,
      handler: HTTPHandler,
      opts?: RouteOptions,
    ) {
      return this.on(method, route, handler, opts);
    };
  }

  return H3;
})() as unknown as { new (config?: H3Config): H3Type };

